import numpy as np
cands={'1':np.ones_like(x),'x':x,'x2':x**2,'1/x':1/x,'v':v,'v2':v**2,'x/v':x/v,'1/v':1/v,'v/x':v/x,'x*v':x*v,'1/x2':1/x**2,'v/x2':v/x**2,'x2/v':x**2/v,'1/(xv)':1/(x*v),'x3':x**3}
def tryset(names):
    B=np.column_stack([cands[n] for n in names])
    c,_,_,_=np.linalg.lstsq(B,dv_dt,rcond=None); r=dv_dt-B@c
    return np.sum(r**2)/np.sum((dv_dt-dv_dt.mean())**2), dict(zip(names,np.round(c,3)))
